using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Threading;
using System.Windows.Forms;
namespace ScreenCraft
{
    static class UtilityTests
    {
        [DllImport("user32.dll")] static extern int GetGuiResources(IntPtr process,int flag);
        sealed class FakeOcr:ILocalOcrBackend
        {
            public ApartmentState Apartment;public Color Pixel;public bool Wait,Fail;
            public readonly ManualResetEvent Entered=new ManualResetEvent(false),Release=new ManualResetEvent(false);
            public OcrCapabilities Capabilities(){return new OcrCapabilities{Languages=new[]{"en-US","zh-Hans-CN"},MaxDimension=10000};}
            public OcrOutcome Read(Bitmap image,string language,CancellationToken token,TimeSpan timeout,Action<int,int> progress){Apartment=Thread.CurrentThread.GetApartmentState();Entered.Set();if(Wait)WaitHandle.WaitAny(new[]{Release,token.WaitHandle});token.ThrowIfCancellationRequested();if(Fail)throw new InvalidOperationException("fixture error");Pixel=image.GetPixel(0,0);if(progress!=null)progress(1,1);return new OcrOutcome{Language=language,Text="建筑\nOCR 123"};}
        }
        sealed class InputCanvas:Canvas
        {
            public InputCanvas(Bitmap b):base(b){ModifierSource=delegate{return Keys.None;};}
            public void ClickAt(PointF p){Point q=ImageToControl(p);OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,q.X,q.Y,0));OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,q.X,q.Y,0));}
        }
        internal static int Pixel(int x,int y){unchecked{uint h=(uint)(x*374761393+y*668265263+17);h=(h^(h>>13))*1274126177;h^=h>>16;return (int)(0xff000000|(h&0xffffff));}}
        sealed class Frames:IScrollFrameSource
        {
            readonly int width,height,header,footer;readonly int[] offsets;int index;public bool Disposed,FailAtEnd,Jitter,Sidebar;public double FractionalStep;
            public Frames(int w,int h,int top,int bottom,params int[] positions){width=w;height=h;header=top;footer=bottom;offsets=positions;}
            public void Read(int[] target){if(index==offsets.Length)throw new IOException(FailAtEnd?"fixture capture failed":"fixture end");double fractional=index*FractionalStep;int extra=(int)Math.Floor(fractional);double blend=fractional-extra;int offset=offsets[index++];for(int y=0;y<height;y++)for(int x=0;x<width;x++){int row=y<header?y-1000:y>=height-footer?y+10000:y-header+offset+extra;int pixel=Pixel(x,row);if(blend>0){int next=Pixel(x,row+1),r=(int)Math.Round(((pixel>>16)&255)*(1-blend)+((next>>16)&255)*blend),g=(int)Math.Round(((pixel>>8)&255)*(1-blend)+((next>>8)&255)*blend),b=(int)Math.Round((pixel&255)*(1-blend)+(next&255)*blend);pixel=Color.FromArgb(r,g,b).ToArgb();}if(Jitter&&index%2==0)pixel=Color.FromArgb(Math.Min(255,((pixel>>16)&255)+1),Math.Min(255,((pixel>>8)&255)+1),Math.Min(255,(pixel&255)+1)).ToArgb();if(Sidebar&&x<16)pixel=Color.FromArgb(120+x,145,180).ToArgb();target[y*width+x]=pixel;}}
            public void Dispose(){Disposed=true;}
        }
        static void Reject<T>(Action action)where T:Exception{try{action();}catch(T){return;}throw new Exception("expected "+typeof(T).Name);}
        static Bitmap Collect(ScrollFrameProcessor processor,Frames source,int count,out string message){int[] buffer=new int[128*180];string error=null;try{for(int i=0;i<count;i++){processor.Read(source,buffer);Stitcher.Result state;int added;processor.Push(ref buffer,out state,out added);}}catch(IOException ex){error=ex.Message;}return processor.Complete(false,error,out message);}
        public static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("ocr/language selection prefers simplified Chinese and respects explicit request",delegate{var tags=new[]{"es-ES","en-US","zh-Hant-TW","zh-Hans-CN"};check(Ocr.SelectLanguage("auto",tags)=="zh-Hans-CN","auto language");check(Ocr.SelectLanguage("en",tags)=="en-US","English family");check(Ocr.SelectLanguage("zh-Hant",tags)=="zh-Hant-TW","traditional");check(Ocr.SelectLanguage("zh-Hans",new[]{"zh-Hant-TW"})==null,"silent wrong script fallback");check(Ocr.SelectLanguage("de",tags)==null&&Ocr.SelectLanguage("auto",new string[0])==null,"missing language fallback");});
            run("ocr/CJK normalization preserves English spacing and line breaks",delegate{check(Ocr.NormalizeCjkSpacing("建 筑  平面 Test 123\n中 文 OCR")=="建筑平面 Test 123\n中文 OCR","mixed whitespace");});
            run("ocr/bands cover tall source with overlap and valid prepared dimensions",delegate{var pieces=Ocr.Pieces(new Size(800,4300));check(pieces[0].Y==0&&pieces.Last().Bottom==4300,"coverage");for(int i=1;i<pieces.Count;i++)check(pieces[i-1].Bottom-pieces[i].Top==Ocr.Overlap,"overlap");using(var transparent=new Bitmap(80,40))using(var prepared=Ocr.Prepare(transparent)){check(prepared.Width==200&&prepared.Height==120,"prepared size");check(prepared.GetPixel(50,50).ToArgb()==Color.White.ToArgb(),"transparent background black");}check(Ocr.Scale(16000)<1,"wide image downscale");});
            run("ocr/service snapshots caller pixels and runs MTA off caller thread",delegate{var fake=new FakeOcr{Wait=true};var service=new LocalOcrService(fake);using(var source=new Bitmap(20,20)){source.SetPixel(0,0,Color.Magenta);var task=service.RecognizeAsync(source,"zh-Hans",CancellationToken.None,TimeSpan.FromSeconds(1),null);check(fake.Entered.WaitOne(2000),"worker not started");source.SetPixel(0,0,Color.Blue);fake.Release.Set();check(task.Wait(2000)&&task.Result.Success,"result");check(fake.Apartment==ApartmentState.MTA&&fake.Pixel.ToArgb()==Color.Magenta.ToArgb(),"ownership/thread");}});
            run("ocr/cancellation and backend failure return actionable outcomes",delegate{var fake=new FakeOcr{Wait=true};var service=new LocalOcrService(fake);using(var source=new Bitmap(10,10))using(var cancel=new CancellationTokenSource()){var task=service.RecognizeAsync(source,"en",cancel.Token,TimeSpan.FromSeconds(1),null);check(fake.Entered.WaitOne(10000),"cancellation worker was not scheduled within harness deadline");cancel.Cancel();check(task.Wait(10000),"cancellation worker did not settle within harness deadline");check(task.Result.Cancelled,"backend returned non-cancelled outcome: "+task.Result.Error);fake.Wait=false;fake.Fail=true;var failed=service.RecognizeAsync(source,"en",CancellationToken.None,TimeSpan.FromSeconds(1),null);check(failed.Wait(10000),"failure worker did not settle within harness deadline");check(!failed.Result.Success&&failed.Result.Error.Contains("fixture error"),"error swallowed");Reject<ArgumentOutOfRangeException>(delegate{service.RecognizeAsync(source,"en",CancellationToken.None,TimeSpan.Zero,null);});}});
            run("ocr/native boundary checks cancellation and timeout before recognition",delegate{using(var b=new Bitmap(8,8))using(var c=new CancellationTokenSource()){c.Cancel();check(Ocr.ReadLocal(b,"auto",c.Token,TimeSpan.FromSeconds(1),null).Cancelled,"native cancellation");check(Ocr.ReadLocal(b,"auto",CancellationToken.None,TimeSpan.Zero,null).TimedOut,"native deadline");}});
            run("ocr/result window exposes editable preview and controls without showing",delegate{using(var f=new OcrResultWindow(new Bitmap(10,10),"auto",new LocalOcrService(new FakeOcr()))){f.CreateControl();check(!f.Visible,"visible");var controls=Descendants(f).ToArray();check(controls.OfType<TextBox>().Any(t=>t.Multiline&&!t.ReadOnly),"preview not editable");check(controls.Any(c=>c.Text=="复制文字")&&controls.Any(c=>c.Text=="取消识别")&&controls.Any(c=>c.Text=="识别／重试"),"controls absent");}});
            run("color/HEX RGB HSL exact values independent of locale",delegate{check(ColorValues.Format(Color.FromArgb(171,12,239),"HEX",true)=="#AB0CEF","HEX");check(ColorValues.Format(Color.FromArgb(171,12,239),"HEX",false)=="#ab0cef","lower HEX");check(ColorValues.Format(Color.Red,"RGB",true)=="rgb(255, 0, 0)","RGB");check(ColorValues.Format(Color.Red,"HSL",true)=="hsl(0, 100%, 50%)","HSL red");check(ColorValues.Format(Color.Gray,"HSL",true)=="hsl(0, 0%, 50.2%)","gray");});
            run("color/frozen physical pixels handle negative origins and DPI conversions",delegate{using(var b=new Bitmap(3,2)){b.SetPixel(2,1,Color.Lime);using(var map=new FrozenColorMap(b,new Rectangle(-1920,-400,3,2))){b.SetPixel(2,1,Color.Red);check(map.Sample(new Point(-1918,-399)).ToArgb()==Color.Lime.ToArgb(),"not frozen or offset");Reject<ArgumentOutOfRangeException>(delegate{map.Sample(new Point(0,0));});}}foreach(int dpi in new[]{96,120,144,192})check(FrozenColorMap.DipToPixel(new PointF(20,40),new Point(-1920,0),dpi)==new Point(-1920+20*dpi/96,40*dpi/96),"DPI");Reject<ArgumentException>(delegate{FrozenColorMap.DipToPixel(new PointF(),Point.Empty,float.NaN);});});
            run("color/production BGR sampler reads exact channels and clamps edges",delegate{IntPtr memory=Marshal.AllocHGlobal(16);try{Marshal.Copy(new[]{0x00123456,0x00abcdef,0x00010203,0x00fedcba},0,memory,4);check(ColorValues.ReadBgra(memory,2,2,new Point(1,0)).ToArgb()==Color.FromArgb(171,205,239).ToArgb(),"BGR order");check(ColorValues.ReadBgra(memory,2,2,new Point(-5,99)).ToArgb()==Color.FromArgb(1,2,3).ToArgb(),"edge clamp");}finally{Marshal.FreeHGlobal(memory);}});
            run("color/synthetic native DIB pixel access releases GDI handles over 200 cycles",delegate{int before=GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);for(int i=0;i<200;i++){var dib=new Dib(64,40);using(var g=dib.Graphics())g.Clear(Color.FromArgb(12,160,230));check(ColorValues.ReadBgra(dib.Bits,64,40,new Point(12,15)).ToArgb()==Color.FromArgb(12,160,230).ToArgb(),"DIB sampling");dib.Dispose();dib.Dispose();}int after=GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);check(after<=before+2,"GDI handles leaked "+before+" -> "+after);File.WriteAllText(Path.Combine(output,"color-gdi-resource-probe.txt"),"Synthetic DIB only; 200 cycles. GDI handles before="+before+", after="+after+". No GetDC desktop capture invoked.");});
            run("color/editor sampling uses source pixel and cancels without annotation",delegate{using(var form=new Form{ClientSize=new Size(600,400)})using(var b=new Bitmap(300,200)){b.SetPixel(80,70,Color.Cyan);using(var canvas=new InputCanvas(new Bitmap(b))){form.Controls.Add(canvas);canvas.Bounds=new Rectangle(0,0,600,400);int calls=0;Color picked=Color.Empty;canvas.BeginColorPick(delegate(Color c){picked=c;calls++;});canvas.ClickAt(new PointF(80,70));check(calls==1&&picked.ToArgb()==Color.Cyan.ToArgb()&&canvas.AnnotationCount==0,"source sample");canvas.BeginColorPick(delegate(Color c){calls++;});canvas.CancelGesture();check(!canvas.Busy&&calls==1,"cancel");canvas.BeginColorPick(delegate(Color c){calls++;});canvas.SetTool(Tool.Rect);canvas.ClickAt(new PointF(100,100));check(calls==1&&!form.Visible,"tool change sampling leak");}}});
            run("scroll/overlap duplicate frames compose exact ordered pixels",delegate{using(var p=new ScrollFrameProcessor(128,180,0,30000))using(var f=new Frames(128,180,0,0,0,40,80,80,120)){string message;using(var b=Collect(p,f,5,out message)){check(message==null&&b.Height==300,"height/order");for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)check(b.GetPixel(x,y).ToArgb()==Pixel(x,y),"seam at "+x+","+y);b.Save(Path.Combine(output,"scroll-synthetic-stitched.png"));}}});
            run("scroll/sticky header footer are included once with correct body",delegate{using(var p=new ScrollFrameProcessor(128,180,0,30000))using(var f=new Frames(128,180,20,15,0,40,80,120)){string message;using(var b=Collect(p,f,4,out message)){check(b.Height==300,"sticky height "+b.Height);for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){int source=y<20?y-1000:y>=b.Height-15?y-120+10000:y-20;check(b.GetPixel(x,y).ToArgb()==Pixel(x,source),"sticky seam at "+y);}b.Save(Path.Combine(output,"scroll-sticky-synthetic.png"));}}});
            run("scroll/upward and lost overlap do not append corrupt rows",delegate{using(var p=new ScrollFrameProcessor(128,180,0,30000))using(var f=new Frames(128,180,0,0,0,60,20,900)){var buffer=new int[128*180];Stitcher.Result state;int added;for(int i=0;i<2;i++){p.Read(f,buffer);p.Push(ref buffer,out state,out added);}p.Read(f,buffer);p.Push(ref buffer,out state,out added);check(state==Stitcher.Result.Up&&added==0&&p.Stitcher.Height==240,"up appended");p.Read(f,buffer);p.Push(ref buffer,out state,out added);check(state==Stitcher.Result.Lost&&p.Stitcher.Height==240,"lost appended");}});
            run("scroll/tolerant matcher handles subtle RGB drift",delegate{using(var p=new ScrollFrameProcessor(128,180,0,30000))using(var f=new Frames(128,180,0,0,0,40,80){Jitter=true}){string message;using(var b=Collect(p,f,3,out message))check(b.Height==260,"RGB drift failed "+b.Height);}});
            run("scroll/fractional resampling accumulates subpixel shifts",delegate{using(var p=new ScrollFrameProcessor(128,180,0,30000))using(var f=new Frames(128,180,0,0,0,40,80){FractionalStep=.4}){string message;using(var b=Collect(p,f,3,out message))check(Math.Abs(b.Height-261)<=1,"fractional shift failed "+b.Height);}});
            run("scroll/sticky sidebar retains ordered scrolling body",delegate{using(var p=new ScrollFrameProcessor(128,180,0,30000))using(var f=new Frames(128,180,0,0,0,40,80){Sidebar=true}){string message;using(var b=Collect(p,f,3,out message)){check(b.Height==260,"sidebar height");for(int y=0;y<b.Height;y++)check(b.GetPixel(64,y).ToArgb()==Pixel(64,y),"sidebar corrupted body");}}});
            run("scroll/frame failure preserves partial image and explicit error",delegate{var frames=new Frames(128,180,0,0,0,60){FailAtEnd=true};using(frames)using(var p=new ScrollFrameProcessor(128,180,0,30000)){string message;using(var b=Collect(p,frames,3,out message))check(b.Height==240&&message.Contains("仅保留")&&message.Contains("fixture capture failed"),"partial discarded");}check(frames.Disposed,"frame source leaked");});
            run("scroll/limit explicitly reports partial and enforces exact cap",delegate{using(var p=new ScrollFrameProcessor(128,180,0,240))using(var f=new Frames(128,180,0,0,0,80)){string message;using(var b=Collect(p,f,2,out message))check(b.Height==240&&p.Stitcher.IsFull&&message.Contains("剩余页面"),"silent truncation");}Reject<ArgumentOutOfRangeException>(delegate{new Stitcher(10000,5000,0,30000);});});
            run("scroll/cancel empty malformed and completed transactions release safely",delegate{string message;using(var p=new ScrollFrameProcessor(128,180,0,30000)){check(p.Complete(true,null,out message)==null&&message==null,"cancel result");Reject<InvalidOperationException>(delegate{p.Complete(false,null,out message);});}using(var p=new ScrollFrameProcessor(128,180,0,30000)){check(p.Complete(false,"fixture",out message)==null&&message.Contains("fixture"),"empty failure");}using(var s=new Stitcher(128,180,0,30000)){Stitcher.Result state;int added;Reject<ArgumentException>(delegate{s.Add(new int[1],out state,out added);});}});
            run("scroll/segmented PNG export reassembles every pixel and preserves old files",delegate{using(var b=new Bitmap(128,301)){for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)b.SetPixel(x,y,Color.FromArgb(Pixel(x,y)));string folder=Path.Combine(output,"分段输出");Directory.CreateDirectory(folder);string old=Path.Combine(folder,"part-001.png");File.WriteAllText(old,"preserve");var paths=SegmentedPng.Export(b,folder,100);check(paths.Length==4&&File.ReadAllText(old)=="preserve","overwrite or count");int row=0;foreach(string path in paths)using(var part=new Bitmap(path)){for(int y=0;y<part.Height;y++,row++)for(int x=0;x<part.Width;x++)check(part.GetPixel(x,y).ToArgb()==b.GetPixel(x,row).ToArgb(),"split pixels");}check(row==301,"last row lost");}});
            run("preferences/utility defaults and legacy settings survive roundtrip",delegate{string dir=Path.Combine(output,"utility-settings");Directory.CreateDirectory(dir);var store=new PreferenceStore(dir);File.WriteAllText(store.FilePath,"{\"Version\":1,\"Capture\":\"Ctrl+Alt+F2\"}");var p=store.Load();check(p.Color=="Ctrl+Shift+C"&&p.Scroll=="Ctrl+Alt+L"&&p.ColorUpper&&p.OcrLanguage=="auto","legacy defaults");p.OcrLanguage="en";p.ColorFormat="HSL";p.ColorUpper=false;store.Save(p);var saved=store.Load();check(saved.OcrLanguage=="en"&&saved.ColorFormat=="HSL"&&!saved.ColorUpper&&saved.Hotkeys().Count==10,"utility preferences");});
        }
        static System.Collections.Generic.IEnumerable<Control> Descendants(Control root){foreach(Control c in root.Controls){yield return c;foreach(var d in Descendants(c))yield return d;}}
    }
}
